contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(true);
        // capture bank before the call
        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;

        // if we will send ether to c, ensure this contract has enough balance
        if (amount > 0) {
            require(address(this).balance >= amount);
        }

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // after the call, bank must still equal bankBefore
        assert(c.bank() == bankBefore);
    }

    // allow receiving ether so tests can fund this contract
    receive() external payable {}
}

